from pathlib import Path

Rendered = dict[Path, str]

# NetBox is the source, and CI cannot reach it - so drift is caught by running
# `homelab generate --check` against a reachable instance, not by the build.
HEADER = (
    "# GENERATED by 'homelab generate' from NetBox. Do not hand-edit.\n"
    "# Re-run it after changing NetBox; `--check` reports drift.\n"
)

HEADER_HASH_FRR = (
    "! GENERATED by 'homelab generate' from NetBox. Do not hand-edit.\n"
    "! Re-run it after changing NetBox; `--check` reports drift.\n"
)
